// ===== The Cabinet: progress = a wall of 16 drawers + a gear train =====
const GEM = { PAIR: "#f0b94a", SIGNS: "#e0533f", SQUARES: "#c77dff", CHECK: "#4fd1a5", GROUP: "#6aa8ff" };
const Progress = (() => {
  const box = $("#drawers"), gears = $("#gears"); let n = 0, turn = 0;
  box.innerHTML = Array.from({ length: 16 }, () => `<div class="drw"><span class="gem"></span><div class="front"><i></i></div></div>`).join("");
  const gp = (cx, cy, t, r1, r2) => { let d = ""; for (let i = 0; i < t * 2; i++) { const a = (i / (t * 2)) * Math.PI * 2, a2 = ((i + 1) / (t * 2)) * Math.PI * 2, r = i % 2 ? r1 : r2; d += `${i ? "L" : "M"}${cx + Math.cos(a) * r} ${cy + Math.sin(a) * r} L${cx + Math.cos(a2) * r} ${cy + Math.sin(a2) * r} `; } return d + "Z"; };
  const G = [[30, 23, 10, 15, 20], [64, 23, 7, 10, 14], [100, 23, 12, 17, 22], [140, 23, 8, 11, 15], [176, 23, 11, 16, 21], [214, 23, 7, 10, 14], [248, 23, 10, 15, 20]];
  gears.innerHTML = G.map(([x, y, t, a, b], i) => `<g class="gr"><path d="${gp(x, y, t, a, b)}" fill="${i % 2 ? "#8a6420" : "#c9a24a"}" stroke="#2a1906"/><circle cx="${x}" cy="${y}" r="${a * .4}" fill="#1a0f06"/><circle cx="${x}" cy="${y}" r="3" fill="#f4dc92"/></g>`).join("");
  function spin(k) { turn += k; $$(".gr", gears).forEach((g, i) => gsap.to(g, { rotation: (i % 2 ? -1 : 1) * turn * 360 / G[i][2] * 3, svgOrigin: `${G[i][0]} ${G[i][1]}`, duration: 1.2, ease: "power2.out" })); }
  function add(skill, cert) {
    if (n >= 16) { spin(1); return; }
    const d = box.children[n++], gem = $(".gem", d), c = GEM[skill], sure = cert >= .55;
    gem.style.background = sure ? `linear-gradient(135deg, #fff9, ${c} 45%, #0007)` : "transparent";
    gem.style.border = sure ? "none" : `2px dashed ${c}`; gem.style.boxShadow = sure ? `0 0 14px ${c}` : "none";
    spin(1.5); gsap.to($(".front", d), { y: "105%", duration: RM ? 0 : .8, ease: "power3.inOut", delay: RM ? 0 : .2 });
    if (!RM) gsap.from(gem, { scale: 0, duration: .6, delay: .8, ease: "back.out(3)" });
    $("#opened").textContent = n;
  }
  return { add };
})();

const SHEETS = [
  { id: "inlay", title: "Inlay tray", was: "Build the rectangle", now: "Fit dark, mid and brass veneers into one rectangular inlay. When it closes, the edges are the factors.", kept: "First split, order of splits, gaps vs spare pieces." },
  { id: "weights", title: "Brass weights", was: "Split your chips", now: "Hang four brass weights on four engraved plaques. All on one if sure, split if torn.", kept: "The split: a 2–2 between two plaques names the exact doubt." },
  { id: "letters", title: "Sealed letters", was: "Swipe the claims", now: "Each letter makes a claim. Seal it true, seal it false, or return it unsealed.", kept: "Mistake families across 8 claims, plus time on each." },
  { id: "automaton", title: "The automaton", was: "Stop the tape", now: "A writing automaton pens Sam's working. Pull the brake the moment it goes wrong.", kept: "Which step they stop at, and how fast after the slip." },
  { id: "geartrain", title: "Gear train", was: "Assemble the working", now: "Mesh three of six engraved gears in order. Three gears carry a slip.", kept: "Which slip gear, the order, and gears swapped out." },
  { id: "dials", title: "Combination dials", was: "Crack the lock", now: "Two brass dials. The cabinet's needles show what your numbers multiply and add to.", kept: "The search path in the locksmith's ledger; the sign slip caught live." },
  { id: "balance", title: "Brass balance", was: "Always, sometimes, never", now: "Weigh (x + 3)² against x² + 9 on a brass balance as x changes.", kept: "Which values they weighed before deciding." },
  { id: "loupe", title: "Jeweller's loupe", was: "X-ray the answer", now: "Engrave the answer on a plate, then look through the loupe at the two moves beneath.", kept: "Two slips that cancel, exposed layer by layer." },
  { id: "locks", title: "Four locks", was: "Sign quadrant", now: "Four padlocks, each opened by two sign tumblers; then the key ring shows which rule you used.", kept: "The pattern across four sign cases, matched to known rules." },
  { id: "glass", title: "Frosted compartment", was: "Predict, then pick", now: "Write and seal your note first; only then does the frosted glass clear.", kept: "Note vs pick: found by checking, or by factorising." },
  { id: "post", title: "Pneumatic post", was: "The switch-up", now: "Canisters arrive by tube, one after another. The fourth is a look-alike.", kept: "Autopilot vs noticing the switch, from the timing." },
  { id: "telegraph", title: "Telegraph", was: "Typing replay", now: "Your typing is sent as a telegraph tape; every deleted message stays on the tape.", kept: "Discarded messages matched to known mistakes, and pauses." },
  { id: "pegs", title: "Pegboard", was: "Find them all", now: "Set a brass peg at every b that works. Each valid peg reveals its box.", kept: "Completeness, listing order, missing negatives." },
  { id: "boxes", title: "Nested boxes", was: "See the structure", now: "Pack (x + 3) into one small box, and the expression becomes a difference of squares.", kept: "The route chosen, plus 99² − 1 in their head." },
  { id: "curator", title: "The curator's choice", was: "Next best question", now: "The curator chooses which mechanism to try next, and stops when sure.", kept: "Same choice rule; this is Lotus's side, not a student game." },
  { id: "engraver", title: "Engraver's proof", was: "Check what we read", now: "The engraver reads your inscription back and marks anything unclear before striking the hallmark.", kept: "Typing problems kept apart from maths." },
];
const weightSVG = `<svg viewBox="0 0 34 34" width="32" height="32"><path d="M11 9 h12 l4 20 h-20z" fill="url(#bw)" stroke="#5a3d0e"/><rect x="14" y="4" width="6" height="6" rx="2" fill="none" stroke="#c9a24a" stroke-width="2"/><defs><linearGradient id="bw" x1="0" x2="1"><stop offset="0" stop-color="#8a6420"/><stop offset=".5" stop-color="#f4dc92"/><stop offset="1" stop-color="#8a6420"/></linearGradient></defs></svg>`;
const GAMES = {
  inlay: (w, api) => W.tiles(w, api, { prompt: "Fit these veneers into one rectangular inlay with area <span class=\"m\">x² + 5x + 6</span>. How many long strips run down the side?", controlLabel: "Strips down the side", commitLabel: "Glue the inlay", rx: 2 }),
  weights: (w, api) => W.allocate(w, api, { prompt: "Which plaque is the same as this? Hang four brass weights: all on one if you're sure, split them if you're torn.", item: (o) => `<span class="g-anchor" style="width:44px;height:8px;border-radius:4px;background:#5a3d0e"></span><span class="plaque">${o.t}</span>`, token: weightSVG, noun: "weights", trayLabel: "Your weights", doneLabel: "Set the weights", verbPlace: "Hung a weight" }),
  letters: (w, api) => W.judge(w, api, { prompt: "Each letter makes a claim. Seal it <b>true</b> if it's always true, <b>false</b> if it isn't, or return it unsealed if you're not sure.", card: (c, i, n) => `<div class="letter"><header><span>Letter ${i + 1} of ${n}</span><span>By hand</span></header><div class="claim">${c}</div><span class="seal g-mark"></span></div>`, buttons: [{ v: "true", label: "Seal true", mark: "TRUE" }, { v: "false", label: "Seal false", mark: "FALSE", cls: "" }, { v: "null", label: "Return unsealed", mark: "UNSURE" }], exit: (v) => ({ x: v === null ? 0 : v ? 80 : -80, y: v === null ? 60 : 20, rotation: v ? 6 : -6, opacity: 0 }), doneText: "The letter tray is empty" }),
  automaton: (w, api) => W.replay(w, api, { prompt: "A writing automaton is penning Sam's check of <span class=\"m\">x² − x − 6</span>. Pull the brake the moment it writes something wrong.", playLabel: "Wind the automaton", stopLabel: "Pull the brake", fineLabel: "It wrote correctly", cursor: true }),
  geartrain: (w, api) => W.order(w, api, { prompt: "Factorise <span class=\"m\">6xy − 4y − 9x + 6</span> by grouping. Mesh three gears in order. Three of the six carry a slip.", slotLabels: ["Gear 1", "Gear 2", "Gear 3"], poolLabel: "Loose gears", doneLabel: "Engage the train" }),
  dials: (w, api) => W.dials(w, api, { prompt: "The cabinet opens for <span class=\"m\">x² − x − 12</span>. Find two numbers that multiply to −12 and add to −1.", labels: { p: "Dial A", q: "Dial B" }, logTitle: "The locksmith's ledger",
    visual(box, p, q, solved, first) {
      if (first || !$("svg", box)) box.innerHTML = `<svg viewBox="0 0 320 220"><rect x="20" y="16" width="280" height="190" rx="8" fill="#1d4a3f" stroke="#c9a24a" stroke-width="3"/><g id="dA"></g><g id="dB"></g><text x="160" y="196" text-anchor="middle" font-size="13" fill="#f3e6cc" id="dmsg" font-family="Spectral"></text></svg>`;
      const dial = (g, cx, v) => { g.innerHTML = `<circle cx="${cx}" cy="100" r="56" fill="url(#dg)" stroke="#5a3d0e" stroke-width="2"/><defs><radialGradient id="dg" cx="40%" cy="35%"><stop offset="0" stop-color="#f4dc92"/><stop offset=".6" stop-color="#c9a24a"/><stop offset="1" stop-color="#6b4a14"/></radialGradient></defs><circle cx="${cx}" cy="100" r="30" fill="#2a1906"/><text x="${cx}" y="110" text-anchor="middle" font-size="26" fill="#f4dc92" font-family="IBM Plex Mono">${sgn(v)}</text><path d="M${cx - 8} 34 l8 12 l8 -12z" fill="#e88a6c"/>`; };
      dial($("#dA", box), 100, p); dial($("#dB", box), 220, q);
      if (!RM && !first) gsap.fromTo([$("#dA", box), $("#dB", box)], { rotation: -12, svgOrigin: "160 100" }, { rotation: 0, duration: .5, ease: "elastic.out(1,.4)" });
      $("#dmsg", box).textContent = solved ? "Click. The cabinet door swings open." : `multiply ${sgn(p * q)} · add ${sgn(p + q)}`;
    }, onSolve: (box) => gsap.to($("rect", box), { attr: { fill: "#2f6b5c" }, duration: .6 }) }),
  balance: (w, api) => W.compare(w, api, { prompt: "Two formulas for the same square's area. Put them on the brass balance and change x. Are they always equal?", verdicts: [{ v: "always", label: "Always equal" }, { v: "sometimes", label: "Sometimes equal" }, { v: "never", label: "Never equal" }], signLabel: "Record the verdict",
    visual(box, x, A, B, first) {
      if (first || !$("svg", box)) box.innerHTML = `<svg viewBox="0 0 600 280"><rect x="280" y="70" width="40" height="190" fill="#8a6420"/><rect x="230" y="255" width="140" height="18" rx="4" fill="#5a3d0e"/><g id="beam"><rect x="100" y="64" width="400" height="12" rx="6" fill="#c9a24a"/></g><circle cx="300" cy="70" r="10" fill="#f4dc92"/><g id="pL"><path d="M0 0 L-55 100 M0 0 L55 100" stroke="rgba(243,230,204,.5)"/><path d="M-70 100 Q0 136 70 100Z" fill="#c9a24a"/><text y="160" text-anchor="middle" font-size="15" fill="#f3e6cc" font-family="Spectral">(x + 3)²</text><text id="vL" y="186" text-anchor="middle" font-size="22" fill="#f4dc92" font-family="IBM Plex Mono"></text></g><g id="pR"><path d="M0 0 L-55 100 M0 0 L55 100" stroke="rgba(243,230,204,.5)"/><path d="M-70 100 Q0 136 70 100Z" fill="#c9a24a"/><text y="160" text-anchor="middle" font-size="15" fill="#f3e6cc" font-family="Spectral">x² + 9</text><text id="vR" y="186" text-anchor="middle" font-size="22" fill="#f4dc92" font-family="IBM Plex Mono"></text></g></svg>`;
      $("#vL", box).textContent = A; $("#vR", box).textContent = B;
      const o = box._a || (box._a = { a: 0 }), draw = () => { const r = o.a * Math.PI / 180; $("#beam", box).setAttribute("transform", `rotate(${o.a} 300 70)`); $("#pL", box).setAttribute("transform", `translate(${300 - 200 * Math.cos(r)} ${70 - 200 * Math.sin(r)})`); $("#pR", box).setAttribute("transform", `translate(${300 + 200 * Math.cos(r)} ${70 + 200 * Math.sin(r)})`); };
      gsap.to(o, { a: Math.max(-1, Math.min(1, (B - A) / 30)) * 14, duration: RM ? 0 : 1.3, ease: "elastic.out(1,.35)", onUpdate: draw }); draw();
    } }),
  loupe: (w, api) => W.twoMoves(w, api, { prompt: "Factorise <span class=\"m\">x² − x − 6</span> in two moves. The answer is engraved on a plate; then look through the loupe at what's beneath.", performLabel: "Engrave the plate", revealLabel: "Look through the loupe",
    empty: (box) => (box.innerHTML = `<p style="text-align:center;color:var(--muted);padding:40px 0">The engraved plate appears here.</p>`),
    surface: (box, r) => { box.innerHTML = `<div style="display:grid;place-items:center;padding:30px 0"><span class="plaque" style="font-size:1.4rem;padding:12px 26px">(x ${pm(r.b1)})(x ${pm(r.b2)})</span></div>`; if (!RM) gsap.from($(".plaque", box), { scale: .8, opacity: 0, duration: .5, ease: "back.out(2)" }); },
    reveal: (box, r) => { box.insertAdjacentHTML("beforeend", `<div class="loupe" style="position:absolute;left:-120px;top:20px;width:110px;height:110px;border-radius:50%;border:8px solid #c9a24a;box-shadow:0 0 0 3px #5a3d0e, inset 0 0 30px rgba(255,240,200,.4)"></div>`); const lp = $(".loupe", box); gsap.to(lp, { x: box.clientWidth + 240, duration: RM ? 0 : 1, ease: "power2.inOut", onComplete: () => W.layerCards(box, r) }); } }),
  locks: (w, api) => W.quad(w, api, { prompt: "Each padlock factorises with the numbers 2 and 3. Set the two sign tumblers to open it.", names: ["Lock I", "Lock II", "Lock III", "Lock IV"], art: () => `<svg viewBox="0 0 120 110"><path class="shk" d="M38 52 V34 a22 22 0 0 1 44 0 V52" fill="none" stroke="#c9a24a" stroke-width="9" stroke-linecap="round"/><rect x="24" y="50" width="72" height="54" rx="10" fill="#8a6420" stroke="#5a3d0e" stroke-width="2"/><circle cx="60" cy="72" r="7" fill="#1a0f06"/><rect x="57" y="74" width="6" height="14" rx="3" fill="#1a0f06"/></svg>`, onLit: (card) => gsap.to($(".shk", card), { y: -10, rotation: 25, svgOrigin: "82 52", duration: RM ? 0 : .6, ease: "back.out(2)" }), checkLabel: "Check the key ring", rulesTitle: "The key ring: rules students use" }),
  glass: (w, api) => W.predict(w, api, { prompt: "Factorise <span class=\"m\">x² + 2x − 15</span>. Write your answer on a note and seal it. The frosted glass only clears after that.", guessLabel: "Your note:", commitLabel: "Seal my note", coverText: "Frosted glass. It clears once your note is sealed.", peekLabel: "Watch someone peek through the glass" }),
  post: (w, api) => W.rows(w, api, { prompt: "Canisters arrive by pneumatic tube. Open each one quickly: factorise it, or mark it as one that can't be factorised.", rowLabel: (i) => `Canister ${i + 1}`, enter: { y: -40, opacity: 0, duration: .45, ease: "bounce.out" } }),
  telegraph: (w, api) => W.typed(w, api, { prompt: "Type your factorisation of <span class=\"m\">x² + 3x − 10</span> (use - for minus). It goes out by telegraph, and every message you deleted stays on the tape.", submitLabel: "Send by telegraph", outTitle: "Telegraph tape", draftWord: "message", samplesLabel: "Or read someone else's tape" }),
  pegs: (w, api) => W.findAll(w, api, { prompt: "<span class=\"m\">x² + bx + 12</span> splits into two brackets with whole numbers. Set a brass peg at <b>every</b> b that works.", doneLabel: "That's every peg",
    marker: (n) => `<line x1="0" y1="0" x2="0" y2="-30" stroke="#c9a24a" stroke-width="3"/><circle cx="0" cy="-34" r="8" fill="#f4dc92" stroke="#8a6420" stroke-width="2"/><text y="-30" text-anchor="middle" font-size="9" fill="#2a1906" font-family="IBM Plex Mono">${n}</text>`,
    resultArt: (v, p, q, hit) => { const B = 36, k = 2, ww = Math.max(3, B + p * k), hh = Math.max(3, B + q * k); return `<svg viewBox="0 0 80 80"><rect x="10" y="10" width="${B}" height="${B}" fill="none" stroke="rgba(243,230,204,.3)" stroke-dasharray="3 3"/><rect x="10" y="10" width="${ww}" height="${hh}" fill="${hit ? "rgba(226,182,90,.25)" : "none"}" stroke="${hit ? "#e2b65a" : "#e88a6c"}" stroke-width="2" ${hit ? "" : 'stroke-dasharray="4 3"'}/></svg>`; } }),
  boxes: (w, api) => W.module(w, api, { prompt: "Factorise this. What's your first move?", routes: { block: "Pack (x + 3) into one box", expand: "Unpack it: expand the bracket", root: "Square-root each part" },
    idle: (box) => (box.innerHTML = `<p style="color:var(--muted)">The box appears here.</p>`),
    blockVisual(box) { box.innerHTML = `<svg viewBox="0 0 220 180"><rect x="50" y="70" width="120" height="80" rx="6" fill="#6b4423" stroke="#c9a24a" stroke-width="2"/><g id="lid"><rect x="44" y="56" width="132" height="18" rx="4" fill="#a06a3a" stroke="#c9a24a" stroke-width="2"/></g><text id="inbox" x="110" y="40" text-anchor="middle" font-size="20" fill="#f3e6cc" font-family="IBM Plex Mono">(x + 3)</text><text id="lab" x="110" y="118" text-anchor="middle" font-size="30" fill="#f4dc92" font-family="Cinzel" opacity="0">A</text></svg>`;
      return gsap.timeline().to("#lid", { rotation: -40, svgOrigin: "44 64", duration: .4 }).to("#inbox", { attr: { y: 112 }, scale: .7, transformOrigin: "50% 50%", duration: .6, ease: "power3.in" }).to("#inbox", { opacity: 0, duration: .15 }).to("#lid", { rotation: 0, svgOrigin: "44 64", duration: .4, ease: "bounce.out" }).to("#lab", { opacity: 1, duration: .3 }); } }),
  curator: (w, api) => W.nbq(w, api, { prompt: "This is Lotus's side, not a student game. Pick a hidden student. The curator tries whichever mechanism will reveal the most, and stops when sure.", names: { alloc: "Brass weights", typed: "Telegraph", quad: "Four locks", claims: "Sealed letters", lots: "Pegboard" }, colName: "Mechanism", askLabel: "Try the best mechanism" }),
  engraver: (w, api) => W.readback(w, api, { prompt: "Write your factorisation of <span class=\"m\">x² + 5x + 6</span> as an inscription. The engraver reads it back and marks anything unclear before striking the hallmark.", inputLabel: "Your inscription", readTitle: "The engraver reads it as", flagLabel: "PROOF", confirmLabel: "Strike the hallmark", fixLabel: "Take the engraver's fix", stampHTML: `<div class="hallmark">Struck<br>&amp; read<br>back</div>` }),
};
App.init(SHEETS, GAMES, Progress, { prefix: "M-" });
